import docx, win32com.client, os, sys
import build_full_report

word = win32com.client.Dispatch("Word.Application")
word.Visible = False
word.DisplayAlerts = 0

def test_file(fname):
    p = os.path.abspath(fname)
    try:
        d = word.Documents.Open(p)
        pg = d.ComputeStatistics(2)
        d.Close(False)
        print(f"PASSED {fname}: pages={pg}")
        return pg
    except Exception as e:
        print(f"FAILED {fname}: {e}")
        return -1

try:
    # Let's test the full report generated by build_full_report!
    p = build_full_report.build_report()
    test_file(p)
finally:
    word.Quit()
